      "content": "package dsh\n\nimport (\n\t\"bytes\"\n\t\"text/template\"\n\n\t\"github.com/yaoapp/yao/llm\"\n)\n\n// PiAiRoute is an alias for llm.PiAiRoute. Kept so that existing dsh\n// callers and tests can continue to write dsh.PiAiRoute.\ntype PiAiRoute = llm.PiAiRoute\n\n// PiAiModelConfig is an alias for llm.PiAiModelConfig.\ntype PiAiModelConfig = llm.PiAiModelConfig\n\n// ConnectorConfig holds LLM connector settings for cordis.yml rendering.\ntype ConnectorConfig struct {\n\tPiAiRoutes          []PiAiRoute // dsh-llm-pi-ai provider routes\n\tIsWindows           bool\n\tVision              bool\n\tMaxInstructionBytes int // dsh-agent-instructions maxBytes; 0 → 65536\n}\n\nconst cordisTemplate = `# Generated by Yao DSH Runner\n- id: yaoapp-jsonrpc-stream\n  name: '@deepseek-ai/dsh-yaoapp-jsonrpc-stream'\n  config:\n    maxTokensAsSuccess: true\n{{- if .PiAiRoutes }}\n\n- id: llm-pi-ai\n  name: '@deepseek-ai/dsh-llm-pi-ai'\n  config:\n    providers:\n{{- range .PiAiRoutes }}\n      {{ .Name }}:\n        api: {{ .API }}\n        baseURL: {{ .BaseURL }}\n        apiKeyEnv: {{ .APIKeyEnv }}\n{{- if or .NoDeveloperRole .ThinkingFormat }}\n        compat:\n{{- if .NoDeveloperRole }}\n          supportsDeveloperRole: false\n{{- end }}\n{{- if .ThinkingFormat }}\n          thinkingFormat: {{ .ThinkingFormat }}\n{{- end }}\n{{- end }}\n{{- if .Reasoning }}\n        reasoning: {{ .Reasoning }}\n{{- end }}\n{{- if gt .BudgetTokens 0 }}\n        thinkingBudgets:\n          high: {{ .BudgetTokens }}\n{{- end }}\n{{- if .Models }}\n        models:\n{{- range .Models }}\n          - id: {{ .ID }}\n            input: [{{- range $i, $m := .Input }}{{ if $i }}, {{ end }}{{ $m }}{{- end }}]\n{{- if .DisableReasoning }}\n            reasoningEfforts: false\n{{- else if .ReasoningEfforts }}\n            reasoningEfforts:\n{{- range $level, $wire := .ReasoningEfforts }}\n              {{ $level }}: {{ $wire }}\n{{- end }}\n{{- end }}\n{{- if gt .ContextWindow 0 }}\n            contextWindow: {{ .ContextWindow }}\n{{- end }}\n{{- if gt .MaxTokens 0 }}\n            maxTokens: {{ .MaxTokens }}\n{{- end }}\n{{- end }}\n{{- end }}\n{{- end }}\n{{- end }}\n{{- if .Vision }}\n\n- id: attachment-local\n  name: '@deepseek-ai/dsh-attachment-local'\n{{- end }}\n\n- id: subprocess\n  name: '@deepseek-ai/dsh-subprocess-local'\n\n{{- if .IsWindows }}\n\n- id: pwsh\n  name: '@deepseek-ai/dsh-pwsh-local'\n  config:\n    cwd: !!js process.env.DSH_CWD ?? process.cwd()\n    timeoutMs: 120000\n\n- id: shell-env\n  name: '@deepseek-ai/dsh-shell-env'\n\n- id: tool-pwsh\n  name: '@deepseek-ai/dsh-tool-pwsh'\n\n{{- else }}\n\n- id: bash\n  name: '@deepseek-ai/dsh-bash-local'\n  config:\n    cwd: !!js process.env.DSH_CWD ?? process.cwd()\n    timeoutMs: 120000\n\n- id: shell-env\n  name: '@deepseek-ai/dsh-shell-env'\n\n- id: tool-bash\n  name: '@deepseek-ai/dsh-tool-bash'\n  config:\n    enableRunInBackground: false\n\n{{- end }}\n\n- id: working-directory\n  name: '@deepseek-ai/dsh-working-directory'\n\n- id: tool-working-directory\n  name: '@deepseek-ai/dsh-tool-working-directory'\n\n- id: session-projection\n  name: '@deepseek-ai/dsh-session-projection'\n\n- id: agent-instructions\n  name: '@deepseek-ai/dsh-agent-instructions'\n  config:\n    maxBytes: {{ if gt .MaxInstructionBytes 0 }}{{ .MaxInstructionBytes }}{{ else }}65536{{ end }}\n\n- id: timer\n  name: '@deepseek-ai/cordis-plugin-timer'\n\n- id: llm\n  name: '@deepseek-ai/dsh-llm'\n\n- id: session\n  name: '@deepseek-ai/dsh-session'\n\n- id: session-title\n  name: '@deepseek-ai/dsh-session-title'\n  config:\n    fallbackMaxWords: 5\n    fallbackMaxBytes: 40\n    maxTitleBytes: 80\n\n- id: system-prompt\n  name: '@deepseek-ai/dsh-system-prompt'\n  config:\n    persona: !!js process.env.DSH_SYSTEM_PROMPT ?? 'You are a coding agent.'\n\n- id: tools\n  name: '@deepseek-ai/dsh-tools'\n\n- id: agent\n  name: '@deepseek-ai/dsh-agent'\n\n- id: llm-retry\n  name: '@deepseek-ai/dsh-llm-retry'\n\n- id: jobs\n  name: '@deepseek-ai/dsh-jobs-local'\n\n- id: agent-loop\n  name: '@deepseek-ai/dsh-agent-loop'\n  config:\n    agents: []\n\n- id: subagent\n  name: '@deepseek-ai/dsh-subagent'\n\n- id: subagent-spawn-in-process\n  name: '@deepseek-ai/dsh-subagent-spawn-in-process'\n  config:\n    providerName: spawn\n\n- id: tool-subagent\n  name: '@deepseek-ai/dsh-tool-subagent'\n  config:\n    provider: spawn\n    toolName: subagent\n    enableRunInBackground: false\n\n- id: tool-todo\n  name: '@deepseek-ai/dsh-tool-todo'\n  config:\n    allowParallelInProgress: true\n\n- id: fs-local\n  name: '@deepseek-ai/dsh-fs-local'\n  config:\n    cwd: !!js process.env.DSH_CWD ?? process.cwd()\n\n- id: fs-observation-policy\n  name: '@deepseek-ai/dsh-fs-observation-policy'\n\n- id: tool-fs\n  name: '@deepseek-ai/dsh-tool-fs'\n\n- id: token-meter\n  name: '@deepseek-ai/dsh-token-meter'\n\n- id: compaction-basic\n  name: '@deepseek-ai/dsh-compaction-basic'\n  config:\n    thresholdRatio: 0.8\n    retainRatio: 0.16\n    maxTokens: 8192\n\n- id: skill-registry\n  name: '@deepseek-ai/dsh-skill'\n\n- id: tool-skill\n  name: '@deepseek-ai/dsh-tool-skill'\n\n- id: skill-office\n  name: '@deepseek-ai/dsh-skill-office'\n  config:\n    cli: false\n    assetRoot: !!js process.env.DSH_OFFICE_ASSET_ROOT\n\n- id: sessions\n  name: '@deepseek-ai/dsh-session-persistence-jsonl'\n  config:\n    root: !!js process.env.DSH_SESSION_ROOT ?? './.sessions'\n    compression: none\n\n- id: session-checkpoints\n  name: '@deepseek-ai/dsh-session-checkpoint-policy'\n`\n\nvar cordisConfigTmpl = template.Must(template.New(\"cordis\").Parse(cordisTemplate))\n\n// RenderCordisConfig generates cordis.yml content from connector settings.\nfunc RenderCordisConfig(cfg *ConnectorConfig) ([]byte, error) {\n\tvar buf bytes.Buffer\n\tif err := cordisConfigTmpl.Execute(&buf, cfg); err != nil {\n\t\treturn nil, err\n\t}\n\treturn buf.Bytes(), nil\n}\n"
