      "content": "package task\n\nimport (\n\t\"container/heap\"\n\t\"sync\"\n)\n\n// QuotaManager manages per-team concurrent execution limits with priority queue\ntype QuotaManager struct {\n\tmu      sync.Mutex\n\trunning map[string]int\n\tqueue   map[string]*priorityQueue\n\tlimits  map[string]int\n}\n\ntype queueEntry struct {\n\tchatID   string\n\tteamID   string\n\tpriority int\n\tindex    int\n\tready    chan struct{}\n}\n\n// GlobalQuota is the singleton quota manager\nvar GlobalQuota = &QuotaManager{\n\trunning: make(map[string]int),\n\tqueue:   make(map[string]*priorityQueue),\n\tlimits:  make(map[string]int),\n}\n\nconst defaultQuotaLimit = 9\n\n// TryAcquire atomically checks and increments running count.\n// Returns true if slot acquired, false if at limit.\nfunc (qm *QuotaManager) TryAcquire(teamID, roleID string) bool {\n\tqm.mu.Lock()\n\tdefer qm.mu.Unlock()\n\tlimit := qm.resolveLimit(teamID, roleID)\n\tif qm.running[teamID] >= limit {\n\t\treturn false\n\t}\n\tqm.running[teamID]++\n\treturn true\n}\n\n// Release decrements running count and signals next queued entry\nfunc (qm *QuotaManager) Release(teamID string) {\n\tqm.mu.Lock()\n\tdefer qm.mu.Unlock()\n\tqm.running[teamID]--\n\tif qm.running[teamID] < 0 {\n\t\tqm.running[teamID] = 0\n\t}\n\tpq := qm.queue[teamID]\n\tif pq != nil && pq.Len() > 0 {\n\t\tnext := heap.Pop(pq).(*queueEntry)\n\t\tqm.running[teamID]++\n\t\tclose(next.ready)\n\t}\n}\n\n// Enqueue adds a task to the priority queue, returns entry with ready channel\nfunc (qm *QuotaManager) Enqueue(teamID, chatID string, priority int) *queueEntry {\n\tqm.mu.Lock()\n\tdefer qm.mu.Unlock()\n\tpq := qm.queue[teamID]\n\tif pq == nil {\n\t\tpq = &priorityQueue{}\n\t\theap.Init(pq)\n\t\tqm.queue[teamID] = pq\n\t}\n\tentry := &queueEntry{\n\t\tchatID:   chatID,\n\t\tteamID:   teamID,\n\t\tpriority: priority,\n\t\tready:    make(chan struct{}),\n\t}\n\theap.Push(pq, entry)\n\treturn entry\n}\n\n// Dequeue removes a specific entry from the queue (e.g. on cancel)\nfunc (qm *QuotaManager) Dequeue(teamID, chatID string) {\n\tqm.mu.Lock()\n\tdefer qm.mu.Unlock()\n\tpq := qm.queue[teamID]\n\tif pq == nil {\n\t\treturn\n\t}\n\tfor i, e := range *pq {\n\t\tif e.chatID == chatID {\n\t\t\theap.Remove(pq, i)\n\t\t\treturn\n\t\t}\n\t}\n}\n\n// QueuePosition returns current position in queue (1-based), 0 if not found\nfunc (qm *QuotaManager) QueuePosition(teamID, chatID string) int {\n\tqm.mu.Lock()\n\tdefer qm.mu.Unlock()\n\tpq := qm.queue[teamID]\n\tif pq == nil {\n\t\treturn 0\n\t}\n\tfor i, e := range *pq {\n\t\tif e.chatID == chatID {\n\t\t\treturn i + 1\n\t\t}\n\t}\n\treturn 0\n}\n\nfunc (qm *QuotaManager) resolveLimit(teamID, roleID string) int {\n\tif limit, ok := qm.limits[teamID]; ok {\n\t\treturn limit\n\t}\n\treturn defaultQuotaLimit\n}\n\n// priorityQueue implements heap.Interface\n// Higher priority number = higher priority; same priority uses insertion order\ntype priorityQueue []*queueEntry\n\nfunc (pq priorityQueue) Len() int { return len(pq) }\nfunc (pq priorityQueue) Less(i, j int) bool {\n\tif pq[i].priority != pq[j].priority {\n\t\treturn pq[i].priority > pq[j].priority\n\t}\n\treturn pq[i].index < pq[j].index\n}\nfunc (pq priorityQueue) Swap(i, j int) {\n\tpq[i], pq[j] = pq[j], pq[i]\n\tpq[i].index = i\n\tpq[j].index = j\n}\nfunc (pq *priorityQueue) Push(x interface{}) {\n\tn := len(*pq)\n\tentry := x.(*queueEntry)\n\tentry.index = n\n\t*pq = append(*pq, entry)\n}\nfunc (pq *priorityQueue) Pop() interface{} {\n\told := *pq\n\tn := len(old)\n\tentry := old[n-1]\n\told[n-1] = nil\n\tentry.index = -1\n\t*pq = old[:n-1]\n\treturn entry\n}\n\n// QuotaStatus represents the current quota usage for a team\ntype QuotaStatus struct {\n\tLimit   int `json:\"limit\"`\n\tRunning int `json:\"running\"`\n\tQueued  int `json:\"queued\"`\n}\n\n// GetStatus returns the current quota status for a team\nfunc (qm *QuotaManager) GetStatus(teamID string) QuotaStatus {\n\tqm.mu.Lock()\n\tdefer qm.mu.Unlock()\n\tlimit := qm.resolveLimit(teamID, \"\")\n\trunning := qm.running[teamID]\n\tqueued := 0\n\tif pq := qm.queue[teamID]; pq != nil {\n\t\tqueued = pq.Len()\n\t}\n\treturn QuotaStatus{Limit: limit, Running: running, Queued: queued}\n}\n"
